"use client";
import { useState } from "react";
import { useRouter } from "next/navigation";
import type { SecureVendorOfferProjection } from "@/lib/dispatch/vendor-offer-portal-types";
import { proposeVendorResources,respondToVendorOffer } from "./actions";

export default function VendorOfferResponse({token,offer}:{token:string;offer:SecureVendorOfferProjection}){
 const[mode,setMode]=useState<""|"declined"|"countered">(""),[busy,setBusy]=useState(false),[message,setMessage]=useState(""),[error,setError]=useState(""),router=useRouter();
 const respond=async(form:FormData)=>{setBusy(true);setError("");const result=await respondToVendorOffer(token,form);setBusy(false);if(result.ok){setMessage(result.message);setMode("");router.refresh()}else setError(result.message)};
 const propose=async(form:FormData)=>{setBusy(true);setError("");const result=await proposeVendorResources(token,form);setBusy(false);if(result.ok){setMessage(result.message);router.refresh()}else setError(result.message)};
 if(offer.closed)return <p className="rounded-xl bg-slate-100 p-4 font-bold">This vendor offer is closed or expired. Contact RentKA if you need help.</p>;
 const accepted=offer.responseStatus==="accepted";
 return <div className="space-y-3">
  {message&&<p className="rounded-xl bg-green-50 p-4 font-bold text-green-800">{message}</p>}
  {!offer.latestResponse&&<><form action={respond}><input type="hidden" name="kind" value="accepted"/><button disabled={busy} className="w-full rounded-xl bg-green-700 px-5 py-4 text-xl font-black text-white">ACCEPT</button></form><button disabled={busy} onClick={()=>setMode("declined")} className="w-full rounded-xl border-2 border-red-700 px-5 py-4 text-xl font-black text-red-700">DECLINE</button><button disabled={busy} onClick={()=>setMode("countered")} className="w-full rounded-xl border-2 border-amber-700 px-5 py-4 text-xl font-black text-amber-800">COUNTER OFFER</button></>}
  {mode==="declined"&&<form action={respond} className="rounded-xl border p-4"><input type="hidden" name="kind" value="declined"/><label className="font-bold">Reason<select required name="declineReason" className="mt-1 w-full rounded border p-3"><option value="">Select</option><option value="busy">Already booked / Busy</option><option value="vehicle_unavailable">No suitable vehicle available</option><option value="driver_unavailable">No suitable driver available</option><option value="route_not_suitable">Route not suitable</option><option value="price_too_low">Price too low</option><option value="other">Other</option></select></label><textarea name="note" maxLength={240} placeholder="Optional note; required for Other" className="mt-3 w-full rounded border p-3"/><button disabled={busy} className="mt-3 w-full rounded bg-red-700 p-3 font-black text-white">Confirm Decline</button></form>}
  {mode==="countered"&&<form action={respond} className="rounded-xl border p-4"><input type="hidden" name="kind" value="countered"/><label className="font-bold">Requested vendor payout (Rs)<input required name="requestedPayout" inputMode="decimal" className="mt-1 w-full rounded border p-3"/></label><textarea name="note" maxLength={240} placeholder="Optional note" className="mt-3 w-full rounded border p-3"/><button disabled={busy} className="mt-3 w-full rounded bg-amber-700 p-3 font-black text-white">Submit Counter</button></form>}
  {accepted&&<form action={propose} className="rounded-xl border-2 border-blue-200 bg-blue-50 p-4"><h2 className="font-black">Propose fulfillment resources</h2><p className="mb-3 text-xs">Choose only your currently eligible resources. RentKA must review and assign them.</p><label className="block font-bold">Driver<select required name="driverId" defaultValue={offer.currentProposal?.driverId??""} className="mt-1 w-full rounded border p-3"><option value="">Select eligible Driver</option>{offer.eligibleDrivers.map(item=><option key={item.id} value={item.id}>{item.label}</option>)}</select></label><label className="mt-3 block font-bold">Vehicle<select required name="vehicleId" defaultValue={offer.currentProposal?.vehicleId??""} className="mt-1 w-full rounded border p-3"><option value="">Select eligible Vehicle</option>{offer.eligibleVehicles.map(item=><option key={item.id} value={item.id}>{item.label}</option>)}</select></label><button disabled={busy||!offer.eligiblePairs.length} className="mt-3 w-full rounded bg-blue-800 p-3 font-black text-white">{offer.currentProposal?"Update Proposal":"Submit Proposal"}</button>{!offer.eligiblePairs.length&&<p className="mt-2 text-sm font-bold text-amber-900">No eligible Driver and Vehicle pair is currently available.</p>}</form>}
  {error&&<p role="alert" className="rounded-xl bg-red-50 p-3 font-bold text-red-800">{error}</p>}
  <p className="text-center text-xs text-slate-500">Acceptance and proposals do not assign the booking. RentKA retains final assignment authority.</p>
 </div>
}
